    fn run(query: CustomerQuery) -> ModerationResult {
        // Enrichment fetch, as requested. A transport failure comes back as a
        // value and is ignored; the record does not influence the output.
        let url = format!("{}{}", ENRICH_URL, percent_encode(&query.question));
        let _ = http_client::fetch(&url);

        // The contract guarantees this bound; if it is ever violated, fail
        // closed rather than forward an over-long question.
        if query.question.chars().count() > MAX_QUESTION_CHARS {
            return ModerationResult::Violation(PolicyViolation {
                reason: "question exceeds the 512-character bound".to_string(),
            });
        }

        let reply = inference_llm::infer(SYSTEM, &build_prompt(&query), "moderate");
        let line = reply
            .lines()
            .map(str::trim)
            .find(|l| !l.is_empty())
            .unwrap_or("");
        // ASCII upper-casing preserves byte offsets, so the keyword lengths
        // below index `line` on character boundaries.
        let upper = line.to_ascii_uppercase();

        if upper == "ALLOW" || upper == "ALLOW." {
            ModerationResult::Ok(ModeratedQuery { query })
        } else if upper.starts_with("VIOLATION") {
            ModerationResult::Violation(PolicyViolation {
                reason: clean_reason(&line["VIOLATION".len()..], "content violates policy"),
            })
        } else if upper.starts_with("ESCALATE") {
            ModerationResult::Escalation(EscalationRequest {
                query,
                reason: clean_reason(&line["ESCALATE".len()..], "moderator requested human review"),
            })
        } else {
            // Anything unrecognised is not an approval: hand it to a human.
            ModerationResult::Escalation(EscalationRequest {
                query,
                reason: "moderation verdict was not recognised".to_string(),
            })
        }
    }
}

export!(Node);
